def sanitize(raw: dict) -> dict:
    return {'email': raw['email'].strip().lower(), 'age': int(raw['age'])}

def tag_user(user: dict) -> dict:
    tier = 'senior' if user['age'] >= 25 else 'junior'
    return {**user, 'tier': tier}

